Let's bypass the debug and directly test the tag extraction logic on the actual data.

```bash
# Test tag extraction in isolation using the exact code from categorize.py
python3 << 'EOF'
import json

# Manually define TAG_RULES (copied directly from the file)
TAG_RULES = {
    "llm_orchestration": ["aether","agent-shell","archaeo","deepcli","dep","depmenu","dispatch","dispatch-adaptive","dispatch-parallel","fore","forensic-query","fts-query","logged","map","map-build","map-func","map-graph","map-query","map-set","mdot","mfull","mkprofile","mmap","mtree","mupdate","oracle","promote","task-list","task-watch","truth-report","tui","workflow","workspace-check"],
    "harmony_hub": ["account-activity","forensic-query","fts-query","workflow","workspace-check"],
    "archwiz": ["archwiz","aether"],
}

def extract_tags(name):
    tags = set()
    for tag, patterns in TAG_RULES.items():
        for pat in patterns:
            if pat.endswith('*'):
                if name.startswith(pat[:-1]):
                    tags.add(tag)
            elif name == pat:
                tags.add(tag)
    if not tags:
        tags.add("other")
    return sorted(tags)

# Test with actual alias names
test_names = ["map", "account-activity", "archwiz", "aether", "agent-shell", "forensic-query"]
for n in test_names:
    print(f"{n}: {extract_tags(n)}")
EOF
```

This isolates exactly what tags each alias gets. The output will tell us if the problem is in the rules or somewhere downstream.

